const item = $input.first();
// o $input é sintaxe do n8n e o first garante que será a primeira resposta dada

const stdout = item.json.stdout || ''; 
// Pega todo o stdout do últimno node ou gera vazio, para evitar bug

const arquivos = stdout
  .split(/\r?\n/)   // Separa os itens pelo \n e \r  (se tiver) 
  .map(linha => linha.trim())  // tira os espaços de cada linha
  .filter(Boolean);  // Remove valores "false", como linhas ""




// Aceita somente PDFs cujo nome seja formado por números
const arquivosNF = arquivos.filter(arquivo =>
  /^\d+\.pdf$/i.test(arquivo)  
// o .test faz false ou true para ver se é válido perante o regex
// Do começo (/^) ao fim da string ($), deve haver um ou mais  números (\d+) seguidos exatamente de .pdf (\.pdf). O \i significa case-insensitive
);


if (arquivosNF.length === 0) {
  return [];  // se não passar nenhum arquivo, retorna vazio
}

  // tranfoorma cada item em um objeto JSON 
return arquivosNF.map(arquivo => ({
  json: {
    arquivo,   
    // pega a variavel arquivo 
    caminho: `Z:/${arquivo}`,
    // pega o caminha (sempre Z: + nome do arquivo)
    status: 'PDF com nome de NF encontrado'
    // gera o status como string
  }
}));



/* Pega a saída textual do comando dir, transforma as linhas em uma lista JavaScript, limpa e valida os nomes dos arquivos e converte cada PDF válido em um item independente do n8n.*/

const item = $input.item;

const base64 = item.json.stdout;

if (!base64) {
  throw new Error(`O PDF ${item.json.arquivo} não retornou dados em Base64.`);
}

return {
  json: {
    arquivo: item.json.arquivo,
    caminho: item.json.caminho,
    status: 'PDF carregado'
  },
  binary: {
    data: {
      data: base64.trim(),
      mimeType: 'application/pdf',
      fileName: item.json.arquivo
    }
  }
};

const items = $input.all();
const resultados = [];

for (const item of items) {
  const texto = item.json.text || '';
  if (!texto) { continue; }


let matchNF = texto.match(
  /\bNF\s*[-:]?\s*([\d\s,-]+?)\s*(?:-?\s*VALOR\s+NF\b|ZONA\b)/i

);

if (!matchNF) {
  continue
}

const blocoNF = matchNF[1].trim();

let nfPepsico = blocoNF;
let nfPepsico2 = null;

if (blocoNF.includes('-') || blocoNF.includes(',')) {
  const partes = blocoNF.split(/[,-]/);

  nfPepsico = partes[0].trim();
  nfPepsico2 = partes[1].trim();
}

  // Busca o número da nota da MA2 (corrigido com \b para não pegar a data/identificador)
  const matchNfMa2 = texto.match(
    /N[uú]mero\s+da\s+Nota[\s\S]{0,150}?\b(\d{5,})\b/i
  );
  // (\d{5,}) - Indica que aceita números com pelo menos 5 termos e guarda como a informação de matchNfMa2

  resultados.push({
    json: {
      arquivo: item.json.arquivo,
      caminho: item.json.caminho,
      "NF Remessa PepsiCo": nfPepsico, 
      "NF Remessa PepsiCo 2": nfPepsico2, // Nova chave dinâmica
      "NF MA2": matchNfMa2 ? matchNfMa2[1] : null, // Agora vai extrair "00025069" perfeitamente
      status: 'dados extraídos'
    }
  });
}

return resultados;

const items = $input.all();

const resultados = [];

for (const [index, item] of items.entries()) {
  const data = item.json.data || '';

  // Recupera os dados originais do PDF
  const dadosOriginais = $('EXTRAIR DADOS PDF').all()[index];

  const nfPepsico =
    dadosOriginais?.json?.["NF Remessa PepsiCo"] || null;

  if (!data) {
    continue;
  }

  // Procura o primeiro id="..." dentro da resposta
  const match = data.match(/<m\b[^>]*\bid="([^"]+)"/);
  // O regex busca uma tag <m com a fronteira \b e com um [^>], que diz que deve
  // ignorar ">" (indicando que a tag <m não deve fechar antes do permitido).
  // Após isso pode ter espaços (*) e encontra a palavra "id=", ignorando aspas [^"]
  // e permitindo espaços (+)

  if (!match) {
    console.log('========== EMAIL NÃO ENCONTRADO ==========');
    console.log('NF pesquisada:', nfPepsico);
    console.log('===========================================');
    continue;
  }

  const messageId = match[1];

  resultados.push({
    json: {
      ...item.json,
      nfPepsico,
      messageId
    }
  });
}

return resultados;

const items = $input.all();

const resultados = [];

for (const item of items) {
  const data = item.json.data || '';

  if (!data) {
    continue;
  }

  // Procura a parte MIME que contém o XML
  const match = data.match(
    /<mp\b[^>]*ct="application\/xml"[^>]*filename="([^"]+)"[^>]*part="([^"]+)"/i
  );

  if (!match) {
    continue;
  }

  const xmlFilename = match[1]; 
  // Pegamos o nome do XML arqivado
  const xmlPart = match[2]; 
  // Pegamos a parte que o XML se encontra no email

  resultados.push({
    json: {
      messageId: item.json.messageId,
      xmlPart,
      xmlFilename
    }
  });
}

return resultados;

const items = $input.all();

const validos = [];

for (const item of items) {
  const texto = item.json.text || '';

  if (!texto) {
    console.log('PDF SEM TEXTO');
    continue;
  }

  const temPrefeitura =
    /PREFEITURA DO MUNIC[IÍ]PIO DE S[AÃ]O PAULO/i.test(texto);

  const temNumeroNota =
    /N[uú]mero\s+da\s+Nota/i.test(texto);

  const temDiscriminacao =
    /DISCRIMINA[CÇ][AÃ]O\s+DE\s+SERVI[CÇ]OS/i.test(texto);

const temNF =
  /\bNF\s*[-:]?\s*\d+/i.test(texto);

  const ehNfse =
    temPrefeitura &&
    temNumeroNota &&
    temDiscriminacao &&
    temNF;

  if (!ehNfse) {
    console.log('========== PDF DESCARTADO ==========');
    console.log('Tem Prefeitura:', temPrefeitura);
    console.log('Tem Número da Nota:', temNumeroNota);
    console.log('Tem Discriminação:', temDiscriminacao);
    console.log('Tem NF:', temNF);
    console.log(
      'Trechos com NF:',
      texto.match(/.{0,80}\bNF\b.{0,120}/gi)
    );
    console.log('====================================');

    continue;
  }

  validos.push({
    json: {
      ...item.json,
      status: 'NFS-e válida'
    },
    binary: item.binary
  });
}

return validos;

