const item = $input.item;

// Verifica se o CSV existe
if (!item.binary?.data) {
  throw new Error('O CSV não possui o arquivo binário "data".');
}

// Recupera o conteúdo real do CSV
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer || buffer.length === 0) {
  throw new Error('O CSV está vazio.');
}

// O GERAR CSV já criou o arquivo com o RPS no nome.
// Ex.: 25160.csv → RPS 25160
const nomeArquivoCSV = item.binary.data.fileName;

if (!nomeArquivoCSV) {
  throw new Error('O CSV não possui nome de arquivo.');
}

const numeroRps = nomeArquivoCSV
  .trim()
  .replace(/\.csv$/i, '');

if (!/^\d+$/.test(numeroRps)) {
  throw new Error(
    `Nome de arquivo inesperado: "${nomeArquivoCSV}". RPS extraído: "${numeroRps}".`
  );
}

if (!numeroRps) {
  throw new Error(
    'Não foi possível obter o Número Documento RPS pelo nome do CSV.'
  );
}

// Remove zeros à esquerda para localizar o PDF físico
const numeroPdf = String(numeroRps).replace(/^0+/, '');

if (!numeroPdf) {
  throw new Error(
    `O RPS "${numeroRps}" não possui um número válido para localizar o PDF.`
  );
}

const nomePdf = `${numeroPdf}.pdf`;

return {
  json: {
    ...item.json,

    numeroRps: numeroRps,

    nomeArquivoCSV: `${numeroRps}.csv`,

    base64CSV: buffer.toString('base64'),

    caminhoCSV:
      `\\CAMINHO-SERVIDO-AQUI\\${numeroRps}.csv`,

    caminhoPDF:
      `Z:\\${nomePdf}`
  }
};

