    /\d{5,}\s+(\d{2}\/\d{2}\/\d{4})\s+\d{2}:\d{2}:\d{2}/
  );

  if (!matchDataEmissao) {
    throw new Error(
      `Não foi possível encontrar a Data de Emissão no PDF ${item.json.arquivo || ''}.`
