    /VALOR\s+TOTAL\s+DO\s+SERVI[CÇ]O\s*=\s*R\$\s*([\d.]+,\d{2})/i
  );

  if (!matchValorFrete) {
    throw new Error(
      `Não foi possível encontrar o Valor Total do Serviço no PDF ${item.json.arquivo || ''}.`
    );
  }

  const valorTotalFrete = matchValorFrete[1].replace(/\./g, '');

